"use client"

import { Button } from "@ui-sdk/react/button"
import { memo, type ComponentProps } from "react"

import { activeAttempt, attemptCount } from "@/lib/agent-task-board-model"
import { agentDiffers, effectiveAgent, type TaskView } from "@/lib/agent-task-types"
import type { Instant } from "@/lib/time"
import { cn } from "@/lib/utils"
import { AgentAvatar, UnassignedAvatar, type AgentAvatars } from "@/components/ui/agent-avatar"
import { agentBadgeLabels, agentSummary } from "@/components/ui/agent-badge"
import type { AgentApproval, BoardMode } from "@/components/ui/agent-task-board-primitive"
import { agentTaskBoardLabels, type AgentTaskBoardLabels } from "@/components/ui/agent-task-labels"
import { ProposalActions } from "@/components/ui/proposal-actions"
import { RelativeTime } from "@/components/ui/relative-time"
import { TaskCardChips } from "@/components/ui/task-card-chips"
import { TaskStatusIcon, taskStatusLabels } from "@/components/ui/task-status"

interface TaskDisplayOptions {
  mode?: BoardMode
  /** One `useNow()` per board, passed down. */
  now?: Instant
  locale?: string
  timeZone?: string
  formatCurrency?: (usd: number) => string
  labels?: AgentTaskBoardLabels
  onApproveProposal?: (id: string) => void | Promise<void>
  onRejectProposal?: (id: string) => void | Promise<void>
  agentApproval?: AgentApproval
  /** Makes each dependency chip a button; only dependencies for which `canSelect` is true are pressable. */
  onSelectTask?: (id: string) => void
  canSelect?: (id: string) => boolean
  /** Images, icons or names per provider id; initials on a provider color otherwise. */
  agentAvatars?: AgentAvatars
}

type TaskCardProps = Omit<ComponentProps<"article">, "children" | "onSelect"> &
  TaskDisplayOptions & {
    task: TaskView
    selected?: boolean
  }

function proposalError(error: unknown, labels: AgentTaskBoardLabels) {
  return (error instanceof Error && error.message) || labels.errors.unknown
}

function TaskCardComponent({
  task,
  selected = false,
  mode = "snapshot",
  now,
  locale,
  timeZone,
  formatCurrency,
  labels = agentTaskBoardLabels,
  onApproveProposal,
  onRejectProposal,
  agentApproval,
  onSelectTask,
  canSelect,
  agentAvatars,
  className,
  ...props
}: TaskCardProps) {
  const text = labels.card
  const parts = labels.components
  const attempt = activeAttempt(task)
  const agent = attempt && effectiveAgent(attempt)
  const agentName = agent && agentSummary(agent, attempt.configured, { ...agentBadgeLabels, ...parts.agentBadge })
  const attempts = attemptCount(task)

  return (
    <article
      data-slot="task-card"
      data-task-id={task.id}
      data-status={task.status}
      data-selected={selected ? "" : undefined}
      className={cn(
        "relative flex flex-col gap-inline rounded-lg border bg-card/(--glass-opacity) px-inset-item py-inset-item text-sm text-card-foreground backdrop-surface hover:border-ring data-selected:border-primary data-selected:ring-1 data-selected:ring-primary",
        className,
      )}
      {...props}
    >
      <div className="flex min-w-0 items-center gap-inline">
        <span data-slot="task-card-id" className="font-mono text-xs text-muted-foreground">
          {task.id}
        </span>
        {agent ? (
          <AgentAvatar
            agent={agent}
            avatars={agentAvatars}
            label={agentName}
            title={agentName}
            data-differs={agentDiffers(attempt) ? "" : undefined}
            className="relative z-10 ms-auto"
          />
        ) : (
          <UnassignedAvatar className="ms-auto" />
        )}
      </div>
      <div className="flex min-w-0 items-start gap-inline">
        <TaskStatusIcon
          status={task.status}
          label={parts.taskStatus?.[task.status] ?? taskStatusLabels[task.status]}
          className="relative z-10 h-lh"
        />
        <Button
          data-task-select=""
          data-task-id={task.id}
          aria-label={text.open(task.id, task.title)}
          aria-current={selected ? "true" : undefined}
          title={task.title}
          onClick={() => onSelectTask?.(task.id)}
          className="min-w-0 cursor-pointer text-start leading-snug font-medium outline-none after:absolute after:inset-0 after:rounded-lg focus-visible:after:ring-2 focus-visible:after:ring-ring focus-visible:after:ring-offset-2 focus-visible:after:ring-offset-background"
        >
          <span className="line-clamp-2">{task.title}</span>
        </Button>
      </div>
      <TaskCardChips
        task={task}
        labels={labels}
        now={now}
        locale={locale}
        timeZone={timeZone}
        formatCurrency={formatCurrency}
        onSelectTask={onSelectTask}
        canSelect={canSelect}
      />
      <div data-slot="task-card-footer" className="flex items-center gap-items text-xs text-muted-foreground">
        <span className="min-w-0 truncate">
          {text.updated}{" "}
          <RelativeTime value={task.updatedAt} now={now} locale={locale} timeZone={timeZone} formatStyle="short" />
        </span>
        {attempts > 0 && <span className="ms-auto shrink-0">{text.attempts(attempts)}</span>}
      </div>
      {task.status === "proposed" && (
        <ProposalActions
          taskId={task.id}
          mode={mode}
          onApprove={onApproveProposal}
          onReject={onRejectProposal}
          agentApproval={agentApproval}
          labels={labels.proposals}
          renderError={(error) => proposalError(error, labels)}
          className="relative z-10"
        />
      )}
    </article>
  )
}

const TaskCard = memo(TaskCardComponent)

export { TaskCard, proposalError }
export type { TaskCardProps, TaskDisplayOptions }

import type { AttemptView, TaskView } from "@/lib/agent-task-types"
import type { Instant } from "@/lib/time"
import { RelativeTime } from "@/components/ui/relative-time"

const iconProps = {
  viewBox: "0 0 24 24",
  fill: "none",
  stroke: "currentColor",
  strokeWidth: 2,
  strokeLinecap: "round",
  strokeLinejoin: "round",
  "aria-hidden": true,
} as const

function AnalysisModeIcon({ mode, label }: { mode: NonNullable<TaskView["analysisMode"]>; label: string }) {
  return (
    <span data-slot="task-card-analysis" data-mode={mode} title={label} className="relative z-10 text-muted-foreground">
      <svg {...iconProps} className="size-4">
        {mode === "review" ? (
          <>
            <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z" />
            <circle cx="12" cy="12" r="3" />
          </>
        ) : (
          <path d="M13 2 4 14h7l-1 8 9-12h-7l1-8Z" />
        )}
      </svg>
      <span className="sr-only">{label}</span>
    </span>
  )
}

type TaskBlockerProps = {
  blocker: NonNullable<AttemptView["blocker"]>
  retryLabel: string
  now?: Instant
  locale?: string
  timeZone?: string
}

function TaskBlocker({ blocker, retryLabel, ...time }: TaskBlockerProps) {
  return (
    <p
      data-slot="task-card-blocker"
      className="relative z-10 flex max-w-full min-w-0 items-start gap-inline rounded-md border border-destructive/40 px-inset-chip py-inset-chip text-xs text-destructive"
    >
      <svg {...iconProps} className="h-lh w-3 shrink-0">
        <path d="M12 9v4M12 17h.01M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z" />
      </svg>
      <span className="min-w-0">
        {blocker.summary}
        {blocker.retryAt && (
          <span className="text-muted-foreground">
            {" · "}
            {retryLabel} <RelativeTime value={blocker.retryAt} {...time} />
          </span>
        )}
      </span>
    </p>
  )
}

export { AnalysisModeIcon, TaskBlocker }

import {
  agentTaskBoardLabels as baseLabels,
  agentTaskBoardLabelsEs as baseLabelsEs,
  mergeLabels,
  type AgentTaskBoardLabels as BaseLabels,
  type AgentTaskBoardLabelsInput as BaseLabelsInput,
} from "@/lib/agent-task-board-labels"
import type { TaskStatus } from "@/lib/agent-task-types"
import type { AcceptanceCounts, AcceptanceLabels } from "@/components/ui/acceptance-list"
import { agentBadgeLabelsEs, type AgentBadgeLabels } from "@/components/ui/agent-badge"
import { attemptTimelineLabelsEs, type AttemptTimelineLabels } from "@/components/ui/attempt-timeline-labels"
import type { BoardColumnLabels } from "@/components/ui/board-column"
import { livenessLabelsEs, type LivenessLabels } from "@/components/ui/liveness-indicator"
import { taskStatusLabelsEs } from "@/components/ui/task-status"
import { usageLabelsEs, type UsageLabels } from "@/components/ui/usage"

interface AgentTaskComponentLabels {
  agentBadge?: Partial<AgentBadgeLabels>
  liveness?: Partial<LivenessLabels>
  taskStatus?: Partial<Record<TaskStatus, string>>
  acceptance?: Partial<AcceptanceLabels>
  acceptanceSummary?: (counts: AcceptanceCounts) => string
  usage?: Partial<UsageLabels>
  attemptTimeline?: Partial<AttemptTimelineLabels>
  boardColumn?: Partial<BoardColumnLabels>
}

type AgentTaskBoardLabels = Omit<BaseLabels, "components"> & { components: AgentTaskComponentLabels }
type AgentTaskBoardLabelsInput = Omit<BaseLabelsInput, "components"> & { components?: AgentTaskComponentLabels }

const agentTaskBoardLabels: AgentTaskBoardLabels = baseLabels

const agentTaskBoardLabelsEs: AgentTaskBoardLabels = {
  ...baseLabelsEs,
  components: {
    agentBadge: agentBadgeLabelsEs,
    liveness: livenessLabelsEs,
    taskStatus: taskStatusLabelsEs,
    acceptance: { pass: "Superado", fail: "Fallido", unverified: "Sin verificar", bar: "Criterios de aceptación" },
    acceptanceSummary: ({ pass, fail, unverified }) => {
      const summary = `${pass} de ${pass + fail + unverified} superados`
      return fail > 0 ? `${summary}, ${fail} fallidos` : summary
    },
    usage: usageLabelsEs,
    attemptTimeline: attemptTimelineLabelsEs,
    boardColumn: { collapse: (title) => `Contraer ${title}`, expand: (title) => `Expandir ${title}` },
  },
}

function resolveLabels(labels?: AgentTaskBoardLabelsInput): AgentTaskBoardLabels {
  return labels ? (mergeLabels(baseLabels, labels as BaseLabelsInput) as AgentTaskBoardLabels) : agentTaskBoardLabels
}

export { agentTaskBoardLabels, agentTaskBoardLabelsEs, resolveLabels }
export type { AgentTaskBoardLabels, AgentTaskBoardLabelsInput, AgentTaskComponentLabels }

"use client"

import type { ComponentProps } from "react"

import { activeAttempt, needsDecision, taskCost } from "@/lib/agent-task-board-model"
import type { TaskView } from "@/lib/agent-task-types"
import { cn } from "@/lib/utils"
import { AcceptanceBar, countAcceptance } from "@/components/ui/acceptance-list"
import { colorIndex } from "@/components/ui/agent-avatar"
import type { AgentTaskBoardLabels } from "@/components/ui/agent-task-labels"
import { DependencyChips } from "@/components/ui/dependency-chips"
import { livenessLabels, livenessTones } from "@/components/ui/liveness-indicator"
import { QuantityValue } from "@/components/ui/quantity-value"
import type { StatusTone } from "@/components/ui/status-pill"
import { AnalysisModeIcon, TaskBlocker } from "@/components/ui/task-card-parts"
import type { TaskDisplayOptions } from "@/components/ui/task-card"
import { taskStatusTones } from "@/components/ui/task-status"
import { usageFormatter } from "@/components/ui/usage"

const chipClassName =
  "relative z-10 inline-flex h-5 max-w-full min-w-0 items-center gap-inline rounded-md border px-inset-chip text-xs whitespace-nowrap text-muted-foreground [&_svg]:size-3 [&_svg]:shrink-0"

const toneText: Record<StatusTone, string> = {
  neutral: "text-foreground",
  info: "text-info",
  success: "text-success",
  warning: "text-warning",
  destructive: "text-destructive",
  muted: "text-muted-foreground",
}

const labelDots = ["bg-chart-1", "bg-chart-2", "bg-chart-3", "bg-chart-4", "bg-chart-5"] as const

function Chip({ className, children, ...props }: ComponentProps<"span">) {
  return (
    <span data-slot="task-card-chip" className={cn(chipClassName, className)} {...props}>
      {children}
    </span>
  )
}

type TaskCardChipsProps = Pick<
  TaskDisplayOptions,
  "now" | "locale" | "timeZone" | "formatCurrency" | "onSelectTask" | "canSelect"
> & {
  task: TaskView
  labels: AgentTaskBoardLabels
}

function TaskCardChips({
  task,
  labels,
  now,
  locale,
  timeZone,
  formatCurrency,
  onSelectTask,
  canSelect,
}: TaskCardChipsProps) {
  const text = labels.card
  const parts = labels.components
  const attempt = activeAttempt(task)
  const liveness = attempt?.liveness !== "finished" ? attempt?.liveness : undefined
  // Running and idle are routine: a dot is enough. Waiting and stuck need a person, so they say so.
  const livenessShown = liveness === "waiting_input" || liveness === "suspect_dead"
  const livenessName = liveness && (parts.liveness?.[liveness] ?? livenessLabels[liveness])
  const counts = countAcceptance(task.acceptance)
  const pressable = onSelectTask && task.dependsOn.some((dependency) => canSelect?.(dependency.id) ?? true)

  return (
    <div data-slot="task-card-chips" className="flex min-w-0 flex-wrap items-center gap-items">
      {(liveness || task.analysisMode) && (
        <Chip data-slot="task-card-signals">
          {liveness && (
            <span
              data-slot="task-card-liveness"
              title={livenessName}
              className={cn("inline-flex min-w-0 items-center gap-inline", toneText[livenessTones[liveness]])}
            >
              <span aria-hidden="true" className="relative inline-flex size-1.5 shrink-0">
                {liveness === "running" && (
                  <span className="absolute inset-0 rounded-full bg-current opacity-60 motion-safe:animate-ping motion-reduce:hidden" />
                )}
                <span className="relative size-full rounded-full bg-current" />
              </span>
              <span className={livenessShown ? "truncate" : "sr-only"}>{livenessName}</span>
            </span>
          )}
          {task.analysisMode && (
            <AnalysisModeIcon mode={task.analysisMode} label={text.analysisMode[task.analysisMode]} />
          )}
        </Chip>
      )}
      {task.profile && <Chip className="text-foreground">{task.profile}</Chip>}
      {task.labels?.map((label) => (
        <Chip key={label} className="text-foreground">
          <span
            aria-hidden="true"
            className={cn("size-1.5 shrink-0 rounded-full", labelDots[colorIndex(label, labelDots.length)])}
          />
          <span className="truncate">{label}</span>
        </Chip>
      ))}
      <DependencyChips
        aria-label={text.dependencies(task.id)}
        items={task.dependsOn.map((dependency) => ({
          id: dependency.id,
          label: `${dependency.id} ${dependency.title ?? ""}`.trim(),
          tone: taskStatusTones[dependency.status],
        }))}
        max={1}
        onSelect={pressable ? (id) => (canSelect?.(id) ?? true) && onSelectTask(id) : undefined}
        className="relative z-10 min-w-0"
      />
      {needsDecision(task) && (
        <Chip title={task.decisionNeeded} className="border-warning/40 text-warning">
          {text.decisionNeeded}
        </Chip>
      )}
      {attempt?.blocker && (
        <TaskBlocker blocker={attempt.blocker} retryLabel={text.retry} now={now} locale={locale} timeZone={timeZone} />
      )}
      {(task.attempts.length > 0 || task.usage) && (
        <Chip>
          <span className="sr-only">{text.cost} </span>
          <QuantityValue
            value={taskCost(task)}
            format={usageFormatter("cost", { locale, formatCurrency })}
            labels={parts.usage?.quantity}
            className="text-foreground"
          />
        </Chip>
      )}
      {task.acceptance.length > 0 && (
        <Chip>
          <AcceptanceBar
            counts={counts}
            labels={{ bar: text.acceptance(task.id) }}
            formatSummary={parts.acceptanceSummary}
            className="w-5"
          />
          <span aria-hidden="true" className="tabular-nums">
            {counts.pass}/{task.acceptance.length}
          </span>
        </Chip>
      )}
    </div>
  )
}

export { TaskCardChips }
